USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_GetDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID AND w.CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL WHERE h.REQUISITION_ID=@RequisitionId AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY p WHERE p.EMPLOYEE_ID=@EmployeeId AND p.IS_ACTIVE=1 AND p.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(p.EFFECTIVE_TO IS NULL OR p.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())));IF @requester IS NULL BEGIN SELECT TOP(0) REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_GetReviewContext @RequisitionId BIGINT,@EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,w.CURRENT_STAGE,CASE WHEN r.CONCERN_DIVISION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_HISTORY h WHERE h.REQUISITION_ID=@RequisitionId AND h.TO_STAGE='CONCERN_DIVISION')THEN'CONCERN_DIVISION'ELSE'READY_FOR_PROCUREMENT'END NEXT_STEP_AFTER_APPROVAL,CONVERT(BIT,CASE WHEN r.CONCERN_DIVISION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_HISTORY h WHERE h.REQUISITION_ID=@RequisitionId AND h.TO_STAGE='CONCERN_DIVISION')THEN 1 ELSE 0 END)CAN_FORWARD,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID LEFT JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL AND EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY p WHERE p.EMPLOYEE_ID=@EmployeeId AND p.IS_ACTIVE=1 AND p.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(p.EFFECTIVE_TO IS NULL OR p.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())));END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_GetPending @EmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;IF NOT EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY WHERE EMPLOYEE_ID=@EmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))RETURN;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,u.DISPLAY_NAME REQUESTED_BY_NAME,(SELECT COUNT(*)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)ITEM_COUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID WHERE w.CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND w.COMPLETED_DATE IS NULL AND w.CURRENT_STATUS='PENDING'AND h.CURRENT_STATUS='IN_WORKFLOW'AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT a WHERE a.REQUISITION_ID=h.REQUISITION_ID AND a.ASSIGNMENT_TYPE='PROCUREMENT_AUTHORITY_POOL'AND a.IS_CURRENT=1)ORDER BY h.REQUESTED_DATE;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;DECLARE @next VARCHAR(40);SELECT @next=CASE WHEN r.CONCERN_DIVISION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_HISTORY h WHERE h.REQUISITION_ID=@RequisitionId AND h.TO_STAGE='CONCERN_DIVISION')THEN'CONCERN_DIVISION'ELSE'READY_FOR_PROCUREMENT'END FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND w.COMPLETED_DATE IS NULL;IF @next IS NULL BEGIN SELECT'004'RESULT_CODE,N'Requisition is not pending in the Procurement Authority queue.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'PROCUREMENT_AUTHORITY','PROCUREMENT_AUTHORITY_APPROVE','PROCUREMENT_AUTHORITY',@next,@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN @next ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_Forward @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;IF NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND w.COMPLETED_DATE IS NULL AND r.CONCERN_DIVISION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_HISTORY h WHERE h.REQUISITION_ID=@RequisitionId AND h.TO_STAGE='CONCERN_DIVISION'))BEGIN SELECT'001'RESULT_CODE,N'Forwarding to a Concern Division is not applicable.'RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;RETURN;END;DECLARE @result TABLE(RESULT_CODE VARCHAR(3),RESULT_MESSAGE NVARCHAR(4000),ENTITY_ID BIGINT,REFERENCE_NO VARCHAR(100));INSERT @result EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'PROCUREMENT_AUTHORITY','PROCUREMENT_AUTHORITY_FORWARD','PROCUREMENT_AUTHORITY','CONCERN_DIVISION',@Remarks,@BatchReferenceId;SELECT RESULT_CODE,RESULT_MESSAGE,ENTITY_ID,CASE WHEN RESULT_CODE='000'THEN'CONCERN_DIVISION'ELSE REFERENCE_NO END REFERENCE_NO FROM @result;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF NULLIF(LTRIM(RTRIM(@Remarks)),'')IS NULL BEGIN;THROW 51000,'Remarks are required for rejection.',1;END;IF NOT EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY WHERE EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))BEGIN;THROW 51002,'Actor is not an active Procurement Authority.',1;END;DECLARE @rule BIGINT;SELECT @rule=WORKFLOW_RULE_ID FROM dbo.WORKFLOW_INSTANCE WITH(UPDLOCK,HOLDLOCK)WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND CURRENT_STATUS='PENDING'AND COMPLETED_DATE IS NULL;IF @rule IS NULL BEGIN;THROW 51003,'Requisition is not pending in the Procurement Authority queue.',1;END;IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_HEADER WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STATUS='IN_WORKFLOW'AND IS_ACTIVE=1)BEGIN;THROW 51003,'Invalid workflow state.',1;END;UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='REJECTED',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_STAGE='END',CURRENT_OWNER_TYPE='NONE',CURRENT_OWNER_EMPLOYEE_ID=NULL,CURRENT_OWNER_ORG_UNIT_ID=NULL,CURRENT_STATUS='REJECTED',COMPLETED_DATE=SYSUTCDATETIME(),MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND CURRENT_STAGE='PROCUREMENT_AUTHORITY'AND COMPLETED_DATE IS NULL;INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,'PROCUREMENT_AUTHORITY_REJECT',@ActorEmployeeId,'PROCUREMENT_AUTHORITY','PROCUREMENT_AUTHORITY','END',@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,'PROCUREMENT_AUTHORITY','END','PROCUREMENT_AUTHORITY_REJECT',@ActorEmployeeId,@Remarks,@BatchReferenceId);COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,'END'REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51002 THEN'003'WHEN 51003 THEN'004'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
